<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { obtenerResumen, urlExportacion, urlReporte } from '../services/estadisticas'
import type { Indicador } from '../interfaces/estadisticas.interface'
const now=new Date(),anio=ref(now.getFullYear()),mes=ref(now.getMonth()+1),rows=ref<Indicador[]>([]),periodo=ref(''),loading=ref(false),error=ref('')
const years=Array.from({length:10},(_,i)=>now.getFullYear()-5+i),months=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic']
const totals=computed(()=>rows.value.reduce((a,x)=>({recibidos:a.recibidos+Number(x.total||0),atendidos:a.atendidos+Number(x.atendidos||0),pendientes:a.pendientes+Number(x.pendientes||0)}),{recibidos:0,atendidos:0,pendientes:0})),avance=computed(()=>totals.value.recibidos?Math.round(totals.value.atendidos/totals.value.recibidos*100):0)
function duration(n?:number){if(n==null)return '—';const d=Math.floor(n/1440),h=Math.floor(n%1440/60),m=Math.round(n%60);return `${d?d+' d, ':''}${h} h ${m} min`}
async function load(){loading.value=true;error.value='';try{const r=await obtenerResumen(anio.value,mes.value);rows.value=r.data;periodo.value=r.periodo}catch(e){error.value=e instanceof Error?e.message:'No se pudieron cargar los indicadores.'}finally{loading.value=false}}
function report(type:'totales'|'atendidos'|'pendientes',x:Indicador){window.open(urlReporte(type,periodo.value,x.id),'_blank')}onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Estadísticas</nav><header class="hero"><div class="mark">%</div><div><small>EVAN · COMERCIALIZACIÓN</small><h1>Estadísticas de atención</h1><p>Incidentes comerciales, nivel de atención y tiempos de respuesta.</p></div><label>Año<select v-model="anio" @change="load"><option v-for="x in years" :key="x">{{x}}</option></select></label></header><p v-if="error" class="flash">{{error}}</p><div class="months"><button v-for="(x,i) in months" :key="x" :class="{active:mes===i+1}" @click="mes=i+1;load()">{{x}}</button></div><section class="kpis"><article><small>RECIBIDOS</small><b>{{totals.recibidos}}</b><span>Tickets del período</span></article><article><small>ATENDIDOS</small><b>{{totals.atendidos}}</b><span>Casos finalizados</span></article><article><small>PENDIENTES</small><b>{{totals.pendientes}}</b><span>Requieren atención</span></article><article class="accent"><small>NIVEL DE ATENCIÓN</small><b>{{avance}}%</b><div><i :style="{width:avance+'%'}"></i></div></article></section><section class="toolbar"><div><b>Incidentes comerciales</b><span>Resumen por tipo de atención</span></div><a :href="urlExportacion('interacciones',anio)">Interacciones</a><a :href="urlExportacion('tareas',anio)">Tareas</a><a :href="urlExportacion('tickets',anio)">Tickets {{anio}}</a></section><div v-if="loading" class="empty">Cargando indicadores…</div><div v-else-if="!rows.length" class="empty">No existen resultados para el período seleccionado.</div><section v-else class="table"><header><span>Tipo de atención</span><span>Recibidos</span><span>Atendidos</span><span>Pendientes</span><span>Tiempo promedio</span></header><article v-for="x in rows" :key="x.id"><div><b>{{x.nombre}}</b><div class="progress"><i :style="{width:(x.porcentaje||0)+'%'}"></i></div><small>{{Math.round(x.porcentaje||0)}}% atendido</small></div><button @click="report('totales',x)">{{x.total}}</button><button class="good" @click="report('atendidos',x)">{{x.atendidos||0}}</button><button class="warn" @click="report('pendientes',x)">{{x.pendientes||0}}</button><span>{{duration(x.promedio_minutos)}}</span></article><footer><b>TOTALES</b><strong>{{totals.recibidos}}</strong><strong>{{totals.atendidos}}</strong><strong>{{totals.pendientes}}</strong><span>—</span></footer></section><aside>Los valores seleccionables abren el reporte detallado del concepto y estado para el período consultado.</aside></div></template>
<style scoped>
.page{--a:#1689a5;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:700}.hero small{color:var(--a);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7d898f;font-size:.65rem}.hero label{margin-left:auto;font-size:.52rem}.hero select{display:block;margin-top:3px;padding:7px;border:1px solid #dae2e5;border-radius:6px}.flash{padding:10px;color:#a13f43;background:#fff0f0;font-size:.63rem}.months{margin-top:13px;padding:7px;display:flex;gap:3px;border-radius:9px;background:#fff}.months button{flex:1;padding:8px;border:0;border-radius:5px;color:#718087;background:none;font-size:.52rem}.months .active{color:#fff;background:var(--a)}.kpis{margin-top:12px;display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.kpis article{padding:15px;border-radius:9px;background:#fff}.kpis small,.kpis b,.kpis span{display:block}.kpis small{color:#869299;font-size:.48rem}.kpis b{margin:4px 0;font-size:1.25rem}.kpis span{font-size:.5rem}.kpis .accent{color:#fff;background:var(--a)}.accent small{color:#d9f4f8}.accent div,.progress{height:5px;border-radius:4px;background:#d4e3e6;overflow:hidden}.accent div{margin-top:9px;background:#ffffff55}.accent i,.progress i{height:100%;display:block;background:#fff}.toolbar{margin-top:12px;padding:13px 16px;display:flex;align-items:center;gap:8px;border-radius:9px 9px 0 0;background:#fff}.toolbar div{margin-right:auto}.toolbar b,.toolbar span{display:block;font-size:.6rem}.toolbar span{color:#88949a;font-size:.49rem}.toolbar a{padding:7px 9px;border-radius:5px;color:#277457;background:#edf8f2;text-decoration:none;font-size:.49rem}.table{background:#fff}.table>header,.table article,.table footer{padding:10px 16px;display:grid;grid-template-columns:3fr repeat(4,1fr);align-items:center;gap:8px;border-bottom:1px solid #edf0f2}.table>header{color:#849097;background:#f7f9fa;font-size:.48rem;font-weight:700}.table article{font-size:.53rem}.table article b{font-size:.55rem}.table article small{color:#849097;font-size:.45rem}.progress{margin-top:5px}.progress i{background:var(--a)}.table article button{justify-self:start;border:0;background:none;font-weight:700;text-decoration:underline}.good{color:#23805e}.warn{color:#bd6b2c}.table footer{font-size:.55rem}.empty{padding:50px;text-align:center;background:#fff;font-size:.6rem}aside{margin-top:10px;padding:10px;border-left:3px solid var(--a);background:#eef8fa;font-size:.52rem}@media(max-width:800px){.kpis{grid-template-columns:1fr 1fr}.table{overflow:auto}.table>header,.table article,.table footer{min-width:720px}.toolbar{flex-wrap:wrap}.toolbar div{width:100%}}@media(max-width:500px){.kpis{grid-template-columns:1fr}.months{overflow:auto}.months button{min-width:42px}.hero{flex-wrap:wrap}.hero label{margin-left:0}}
</style>
